{"task": "Find all log messages that contain an email address", "sql": "SELECT ts, service, message FROM logs WHERE regexp_like(message, '[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}')"}
{"task": "Count how many log messages per service contain an email address", "sql": "SELECT service, COUNT(*) AS email_log_count FROM logs WHERE regexp_like(message, '[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}') GROUP BY service ORDER BY email_log_count DESC"}
{"task": "Find error-level log messages that contain an email address, useful for spotting PII leaks in error traces", "sql": "SELECT ts, service, message FROM logs WHERE level = 'ERROR' AND regexp_like(message, '[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}')"}
{"task": "Flag each log row with whether it contains an email address using a CASE expression", "sql": "SELECT ts, service, message, CASE WHEN regexp_like(message, '[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}') THEN 'CONTAINS_EMAIL' ELSE 'NO_EMAIL' END AS pii_flag FROM logs"}
{"task": "Find log messages containing an email address specifically from the gmail.com domain", "sql": "SELECT ts, service, message FROM logs WHERE regexp_like(message, '[A-Za-z0-9._%+-]+@gmail\\.com', 'i')"}
{"task": "Find log messages containing an email address case-insensitively to catch uppercase domains", "sql": "SELECT ts, service, message FROM logs WHERE regexp_like(message, '[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}', 'i')"}
{"task": "Count log messages containing an email address per day to track trend of PII exposure over time", "sql": "SELECT DATE_TRUNC('day', ts) AS day, COUNT(*) AS email_log_count FROM logs WHERE regexp_like(message, '[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}') GROUP BY day ORDER BY day"}
{"task": "Find the most recent 50 log messages that contain an email address for quick manual review", "sql": "SELECT ts, service, level, message FROM logs WHERE regexp_like(message, '[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}') ORDER BY ts DESC LIMIT 50"}
{"task": "Find log messages that contain an email address but exclude ones that also mention 'test' to filter out test fixtures", "sql": "SELECT ts, service, message FROM logs WHERE regexp_like(message, '[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}') AND NOT regexp_like(message, 'test', 'i')"}
{"task": "Join logs and events to find logged email addresses whose messages also reference an HTTP path with a status code of 500", "sql": "SELECT l.ts, l.message, e.path, e.status FROM logs l JOIN events e ON regexp_like(l.message, regexp_replace(e.path, '\\?.*$', '')) WHERE regexp_like(l.message, '[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}') AND e.status = 500"}

